INSERT INTO public.herb_monograph_sources (herb_slug, source, licence, attribution, url, claims, safety, doses, generation_method, monograph_date, retrieved_at) VALUES ('garlic', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=garlic_ail&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help relieve the symptoms associated with upper respiratory tract infections and catarrhal conditions (such as nasal congestion/buildup of excess mucus) (Mills and Bone 2005; ESCOP 2003; Bradley 1992; Felter and Lloyd 1983)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to help reduce elevated blood lipid levels (hyperlipidemia) in adults (Kojuri et al. 2007; Macan et al. 2006; Mills and Bone 2005; ESCOP 2003; Kannar et al. 2001; Blumenthal et al. 2000; Bradley 1992)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to help maintain cardiovascular health in adults (Kojuri et al. 2007; Macan et al. 2006; Mills and Bone 2005; ESCOP 2003; Kannar et al. 2001; Blumenthal et al. 2000; Bradley 1992)."}]'::jsonb, '["Relief of upper respiratory tract infections and catarrhal (nasal congestion) conditions", "Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking blood thinners or protease inhibitors (Brinker 2010; Mills and Bone 2005).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant (Brinker 2010; Mills and Bone 2005).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have diabetes (Brinker 2010; Mills and Bone 2005).", "No statement required.", "Stop use if hypersensitivity/allergy occurs (Brinker 2010; Mills and Bone 2005)."]'::jsonb, '["As specified below", "Subpopulation(s) 1 , 2", "Garlic dried bulb (g/day)", "Minimum", "Maximum", "Children", "2-4 years", "0.08 g", "2 g", "5-9 years", "0.1 g", "3 g", "10-11 years", "0.2 g", "6 g", "Adolescents", "12-14 years", "0.2 g", "6 g", "15-17 years", "0.5 g", "12 g", "Adults", "18 years and older", "0.5 g", "12 g", "1 Children and adolescent doses were calculated as a proportion of the adult dose (JC 2008). The use of garlic in children is supported by the following references: McIntyre 2005; Bove 2001; Schilcher 1997.", "2 Adult dose supported by the following references: Kojuri et al. 2007; Mills and Bone 2005; ESCOP 2003; Kannar et al. 2001; Blumenthal et al. 2000; Bradley 1992.", "Note: Solvents allowed for the method of preparation “Non-Standardized Extracts (Dry extract)” as part of this monograph are ethanol and/or water only.", "Subpopulation(s) 1 , 2", "Minimum (mg/day)", "Maximum (mg/day)", "Allicin", "Alliin", "Allicin", "Alliin", "Children", "2-4 years", "0.17 mg", "0.3 mg"]'::jsonb, 'imported-ogl-canada', '2026-01-30'::date, '2026-11-20'::date) ON CONFLICT (herb_slug, source) DO NOTHING;
INSERT INTO public.herb_monograph_sources (herb_slug, source, licence, attribution, url, claims, safety, doses, generation_method, monograph_date, retrieved_at) VALUES ('turmeric', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=turmeric.oral.curcuma.orale&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants (ESCOP 2003; Blumenthal et al. 2000; Mills and Bone 2000)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants that help fight/protect (cell) against/reduce (the oxidative effect of/the oxidative damage caused by/cell damage caused by) free radicals (ESCOP 2003; Blumenthal et al. 2000; Mills and Bone 2000)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to aid digestion (ESCOP 2003; Williamson 2003; Blumenthal et al. 2000; Mills and Bone 2000)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine to help relieve flatulent dyspepsia (carminative) (Mills and Bone 2005; Blumenthal et al. 2000; Wren 1907)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine as a hepatoprotectant/liver protectant (Boon and Smith 2004; Williamson 2003)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Herbal Medicine to increase bile excretion by the liver (choleretic) and stimulate contraction of the gallbladder (cholagogue) (Mills and Bone 2005; Boon and Smith 2004; Wichtl 2004; Blumenthal et al. 2000; Mills and Bone 2000)."}, {"section": "Use(s) or Purpose(s)", "text": "(Traditionally) used in Herbal Medicine (as an anti-inflammatory) to help relieve joint pain (Winston and Kuhn 2008; Blumenthal et al. 2000; WHO 1999)."}, {"section": "Use(s) or Purpose(s)", "text": "Used in Traditional Chinese Medicine (TCM) to eliminate blood stasis, promote the flow of qi, relieve pain of menstruation due to blood stasis (PPRC 2015; Bensky et al. 2004)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding (ESCOP 2003; Brinker 2001; McGuffin et al. 1997).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you have a liver or biliary disorder (HC 2025; EMA 2018; Brinker 2010; ESCOP 2003; McGuffin et al. 1997).", "Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are taking medications (HC 2025).", "Stop use and ask a health care practitioner/health care provider/health care professional/doctor/physician if you experience any new symptoms including yellowing of the eyes or skin, dark urine, nausea, vomiting, stomach pain (HC 2025).", "All uses except for Source of antioxidants and Hepatoprotectant", "Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "No statement required."]'::jsonb, '["Adults 18 years and older", "Note: ‘decoction’ or ‘infusion’ is listed as an acceptable method of preparation, ‘decoction concentrate’ or ‘infusion concentrate’ is also allowed. This would also apply to standardized methods of preparations.", "Antioxidant", "Not to exceed 9 grams of dried rhizome, per day; For dry extracts, maximum ratio is 10:1 (ESCOP 2003; Williamson 2003; Blumenthal et al. 2000).", "Note: Solvents allowed for the method of preparation “Non-Standardized Extracts (Dry extract)” as part of this monograph are ethanol and/or water only.", "Extract providing up to 35% Curcuminoids; Quantity crude equivalent: not to exceed 9 grams of dried rhizome, per day (Meng et al. 2018; Bagchi 2012; Li et al. 2011; ESCOP 2003; Williamson 2003; Blumenthal et al. 2000).", "Note: Optional: The potency constituent, curcumin, can be included.", "Digestive aid; Relief of flatulent dyspepsia; Hepatoprotectant; Bile excretion; Joint pain", "1 - 9 grams of dried rhizome, per day; For dry extracts, maximum ratio is 10:1 (Mills and Bone 2005; Wichtl 2004; ESCOP 2003; Williamson 2003; Blumenthal et al. 2000).", "Note: Solvents allowed for the method of preparation “Non-Standardized Extracts (Dry extract)” as part of this monograph are ethanol and/or water only.", "Extract providing up to 35% Curcuminoids; Quantity crude equivalent: 1-9 grams of dried rhizome, per day (Meng et al. 2018; Bagchi 2012; Li et al. 2011; Mills and Bone 2005; Wichtl 2004; ESCOP 2003; Williamson 2003; Blumenthal et al. 2000).", "Note: Optional: The potency constituent, curcumin, can be included.", "TCM", "3 - 9 grams of dried rhizome, per day; For dry extracts, maximum ratio is 10:1 (PPRC 2020; Bensky et al. 2004)."]'::jsonb, 'imported-ogl-canada', '2025-09-26'::date, '2026-11-20'::date) ON CONFLICT (herb_slug, source) DO NOTHING;
INSERT INTO public.herb_monograph_sources (herb_slug, source, licence, attribution, url, claims, safety, doses, generation_method, monograph_date, retrieved_at) VALUES ('haematococcus-pluvialis-extract', 'Health Canada', 'ogl-canada', 'Contains information licensed under the Open Government Licence – Canada.', 'https://webprod.hc-sc.gc.ca/nhpid-bdipsn/atReq?atid=haematococcus.pluvialis&lang=eng', '[{"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants (Karppi et al. 2007; Kim and Chyun 2004)."}, {"section": "Use(s) or Purpose(s)", "text": "Source of antioxidants/Provides antioxidants that help fight/protect (cell) against/reduce (the oxidative effect of/the oxidative damage caused by/cell damage caused by) free radicals (Karppi et al. 2007; Kim and Chyun 2004)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps to maintain/support skin health (Tominaga et al. 2012; Yamashita 2006)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps to improve/maintain/support skin moisture/hydration (Ito et al. 2018; Tsukahara et al. 2016; Phetcharat et al. 2015; Yamashita 2006)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps to improve/maintain/support skin elasticity (Tsukahara et al. 2016; Phetcharat et al. 2015; Tominaga et al. 2012; Yamashita 2006)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps to maintain/support skin texture (Ito et al 2018)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps to reduce the appearance of fine lines/wrinkles (Phetcharat et al. 2015; Tominaga et al. 2012; Yamashita 2006)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps to maintain/support eye/ocular health (Hashimoto et al. 2016; Hashimoto et al. 2013; Nakamura et al. 2004)."}, {"section": "Use(s) or Purpose(s)", "text": "Helps to reduce eye strain/eye fatigue (Nagaki et al. 2006; Nitta et al. 2005; Nakamura et al. 2004)."}]'::jsonb, '["Ask a health care practitioner/health care provider/health care professional/doctor/physician before use if you are pregnant or breastfeeding.", "Eye strain, Eye fatigue", "Ask a health care practitioner/health care provider/health care professional/doctor/physician if symptoms persist or worsen.", "No statement required."]'::jsonb, '["Adults 18 years and older.", "Antioxidant", "Preparation/extract providing up to 40 milligrams of astaxanthin, per day; Not to exceed 1 gram of dried broken cells (Ito et al 2018; Hashimoto et al. 2016; Tsukahara et al 2016; Phetcharat and al 2015; EFSA 2014; Hashimoto et al. 2013; Tominaga et al 2012; Earnest et al. 2011; Malmstein and Lignell 2008; Karppi et al. 2007; Iwasaki and Tawara 2006; Nagaki et al. 2006; Yamashita 2006; Nitta et al. 2005; Kim and Chyun 2004; Nakamura et al. 2004).", "Eye strain, Eye fatigue", "Extract providing 6 - 40 milligrams of astaxanthin, per day; Not to exceed 1 gram of dried broken cells, per day (Earnest et al. 2011; Malmstein and Lignell 2008; Iwasaki and Tawara 2006; Nagaki et al. 2006; Nitta et al. 2005; Nakamura et al. 2004).", "Skin health, Skin elasticity, Skin moisture/hydration, Skin texture, Skin appearance of lines/wrinkles, Eye/ocular health", "Extract providing 4 - 40 milligrams of astaxanthin, per day; Not to exceed 1 gram of dried broken cells, per day (Ito et al 2018; Hashimoto et al. 2016; Phetcharat et al 2015; Hashimoto et al. 2013; Tominaga et al 2012; Tsukahara et al 2016; Yamashita 2006; Nakamura et al. 2004)."]'::jsonb, 'imported-ogl-canada', '2025-01-10'::date, '2026-11-20'::date) ON CONFLICT (herb_slug, source) DO NOTHING;
INSERT INTO public.herb_monograph_sources (herb_slug, source, licence, attribution, url, claims, safety, doses, generation_method, monograph_date, retrieved_at) VALUES ('corynanthe-yohimbe', 'NCCIH', 'us-federal-public-domain', 'US government work, not subject to copyright (17 U.S.C. §105).', 'https://www.nccih.nih.gov/health/yohimbe', '["Yohimbe is an evergreen tree native to central and western Africa. It has a compound called yohimbine in its bark. The bark has been used traditionally as an aphrodisiac and sexual performance enhancer, as well as a mild hallucinogen.", "Yohimbe is promoted for erectile dysfunction, athletic performance, weight loss, as a mood booster, and more.", "The amount of yohimbine in dietary supplements may vary; some yohimbe products contain very little yohimbine. Yohimbe sold as a dietary supplement may not work like the prescription medication that contains yohimbine. It is illegal in the United States to market an over-the-counter product containing yohimbine as a treatment for erectile dysfunction without getting approval from the U.S. Food and Drug Administration (FDA) to do so.", "There is not enough research to say whether yohimbe as a dietary supplement is helpful for any condition, including erectile dysfunction, athletic performance, or obesity."]'::jsonb, '["Yohimbine, a component of yohimbe, has been associated with cardiac arrhythmia (irregular heartbeat), blood pressure problems, heart attacks, and seizures.", "Because of inaccurate labeling and potential for serious side effects, yohimbe supplements have been restricted or banned in many countries.", "Yohimbe caused stomach problems, tachycardia (a rapid heartbeat), anxiety, and high blood pressure, according to a study about yohimbe and other substances that compared calls made to the California Poison Control System over a 7-year period. People calling about yohimbe were generally more likely to need medical care than other callers.", "Most yohimbe products don’t say how much yohimbine they contain. The amount may vary a lot among products, according to a 2015 analysis of 49 brands of supplements labeled as containing yohimbe or yohimbine for sale in the United States. Some of the yohimbine was either synthetic or from highly processed plant extracts. Most of the supplements did not provide information about known side effects.", "Do not use yohimbe if you are taking types of antidepressant medications called monoamine oxidase inhibitors or tricyclic antidepressants. Yohimbe can interact with these medications. If you take any type of medicine, talk with your health care provider before using yohimbe or other herbal products; some herbs and medicines interact in harmful ways.", "It might be unsafe to use yohimbe orally (taken by mouth) during pregnancy or while breastfeeding."]'::jsonb, '[]'::jsonb, 'imported-public-domain', NULL, '2026-11-20'::date) ON CONFLICT (herb_slug, source) DO NOTHING;

