INSERT INTO public.herb_monograph_sources (herb_slug, source, licence, attribution, url, claims, safety, doses, generation_method, monograph_date, retrieved_at) SELECT 'wood-avens', source, licence, attribution, url, claims, safety, doses, generation_method, monograph_date, retrieved_at FROM public.herb_monograph_sources WHERE herb_slug = 'herb-bennet' ON CONFLICT (herb_slug, source) DO NOTHING;
DELETE FROM public.herb_monograph_sources WHERE herb_slug = 'herb-bennet';
UPDATE public.herb_regulatory_evidence SET herb_slug = 'wood-avens' WHERE herb_slug = 'herb-bennet' AND NOT EXISTS (SELECT 1 FROM public.herb_regulatory_evidence k WHERE k.herb_slug = 'wood-avens');
DELETE FROM public.herb_regulatory_evidence WHERE herb_slug = 'herb-bennet';
UPDATE public.herb_pubmed_monographs SET slug = 'wood-avens' WHERE slug = 'herb-bennet' AND NOT EXISTS (SELECT 1 FROM public.herb_pubmed_monographs k WHERE k.slug = 'wood-avens');
DELETE FROM public.herb_pubmed_monographs WHERE slug = 'herb-bennet';
UPDATE public.herb_monographs SET herb_id = (SELECT id FROM public.herbs WHERE slug = 'wood-avens'), herb_slug = 'wood-avens' WHERE herb_slug = 'herb-bennet' AND NOT EXISTS (SELECT 1 FROM public.herb_monographs k WHERE k.herb_slug = 'wood-avens');
DELETE FROM public.herb_monographs WHERE herb_slug = 'herb-bennet';
DELETE FROM public.herb_faqs d USING public.herb_faqs k WHERE d.herb_id = (SELECT id FROM public.herbs WHERE slug = 'herb-bennet') AND k.herb_id = (SELECT id FROM public.herbs WHERE slug = 'wood-avens') AND d.question = k.question;
UPDATE public.herb_faqs SET herb_id = (SELECT id FROM public.herbs WHERE slug = 'wood-avens') WHERE herb_id = (SELECT id FROM public.herbs WHERE slug = 'herb-bennet');
INSERT INTO public.drug_interactions (herb_id, drug_name, rxcui, severity, description, mechanism, evidence_level, source, source_url, translations, evidence_note) SELECT k.id, d.drug_name, d.rxcui, d.severity, d.description, d.mechanism, d.evidence_level, d.source, d.source_url, d.translations, d.evidence_note FROM public.drug_interactions d CROSS JOIN (SELECT id FROM public.herbs WHERE slug = 'wood-avens') k WHERE d.herb_id = (SELECT id FROM public.herbs WHERE slug = 'herb-bennet') AND NOT EXISTS (SELECT 1 FROM public.drug_interactions e WHERE e.herb_id = k.id AND lower(e.drug_name) = lower(d.drug_name));
DELETE FROM public.drug_interactions WHERE herb_id = (SELECT id FROM public.herbs WHERE slug = 'herb-bennet');
UPDATE public.herbs SET is_published = false, updated_at = now() WHERE slug = 'herb-bennet' AND is_published;
UPDATE public.herbs SET related_slugs = ARRAY(SELECT x FROM unnest(related_slugs) AS x WHERE NOT (x = ANY(ARRAY['alisma-plantago-aquatica-subsp-orientale', 'angelica-archangelica-l', 'asteraceae-roman-chamomile', 'bassia-scoparia', 'boneset-herb', 'cinnamomum-aromaticum', 'clivers-goosegrass', 'crataegus-monogyna-jacq', 'dioscorea-collettii-var-hypoglauca', 'hansenia-weberbaueriana', 'herb-bennet', 'hydrastis-canadensis', 'linum-usitatissimum-l', 'passiflora-incarnata', 'phyllolobium-chinense', 'qing-pi-liver', 'scutellaria-lateriflora-l', 'senega-officinalis', 'sheng-di-huang-tcm', 'styphnolobium-japonicum', 'vaccinium-myrtillus-l', 'valeriana-officinalis-l', 'vincetoxicum-stauntonii', 'xanthorrhiza-simplicissima-herb']::text[]))) WHERE related_slugs && ARRAY['alisma-plantago-aquatica-subsp-orientale', 'angelica-archangelica-l', 'asteraceae-roman-chamomile', 'bassia-scoparia', 'boneset-herb', 'cinnamomum-aromaticum', 'clivers-goosegrass', 'crataegus-monogyna-jacq', 'dioscorea-collettii-var-hypoglauca', 'hansenia-weberbaueriana', 'herb-bennet', 'hydrastis-canadensis', 'linum-usitatissimum-l', 'passiflora-incarnata', 'phyllolobium-chinense', 'qing-pi-liver', 'scutellaria-lateriflora-l', 'senega-officinalis', 'sheng-di-huang-tcm', 'styphnolobium-japonicum', 'vaccinium-myrtillus-l', 'valeriana-officinalis-l', 'vincetoxicum-stauntonii', 'xanthorrhiza-simplicissima-herb']::text[];

