UPDATE public.herbs SET side_effects = ARRAY['Acute toxicity studies in Wistar rats indicated the methanolic extract was substantially safe up to a single dose of 2,000 mg/kg [PMID:27695635].', 'Pistagremic acid showed safety in acute toxicity tests up to 500 mg/kg p.o. [PMID:27748181].']::text[] WHERE slug = 'pistacia-integerrima' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
UPDATE public.herbs SET contraindications = ARRAY['Cases of poisoning have been reported in humans due to mistaken identity [PMID: 6418273] and in cattle [PMID: 4605867, PMID: 9501389].']::text[] WHERE slug = 'mercurialis-perennis' AND (contraindications IS NULL OR cardinality(contraindications) = 0);
UPDATE public.herbs SET side_effects = ARRAY['Aqueous root extract showed no cytotoxicity to TIG-3 normal human fibroblasts at doses up to 50 μg/ml [PMID:27010955] and no acute oral toxicity in rats [PMID:27097967].']::text[] WHERE slug = 'helicteres-angustifolia' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
UPDATE public.herbs SET side_effects = ARRAY['In rodent studies, an extract of lyophilized fruit pulp showed no apparent toxicity in acute tests (2000 mg/kg) or repeated dose tests (up to 1000 mg/kg for 180 days) [PMID:38061671].', 'Preliminary evaluations of crude acerola polyphenols (C-AP) in rats also indicated safety in acute (2000 mg/kg), subacute, and subchronic doses [PMID:18460146].']::text[] WHERE slug = 'malpighia-emarginata' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
UPDATE public.herbs SET side_effects = ARRAY['Zedoary turmeric oil injection (ZTOI), which can be derived from C. kwangsiensis, has been associated with adverse drug reactions including dyspnea, potentially caused by β-elemene binding to hemoglobin and upregulating HIF-1α [PMID:38042387].']::text[] WHERE slug = 'curcuma-kwangsiensis' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
UPDATE public.herbs SET side_effects = ARRAY['High doses of cardiac glycosides, specifically periplocin, can trigger cardiotoxicity [PMID:26924293, PMID:24872678].', 'However, studies in mice and hamster cells suggest the root bark does not possess mutagenic potential under examined conditions [PMID:22888473].']::text[] WHERE slug = 'periploca-sepium' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
UPDATE public.herbs SET side_effects = ARRAY['Acute oral toxicity in rats occurred at a dose of 1,140 mg/kg [PMID:16871016].', 'In albino Swiss mice, the calculated LD50 for an ethyl acetate extract was 345.9 mg/kg (oral) and 60.8 mg/kg (intraperitoneal) [PMID:15138009].', 'High doses of ethyl acetate extract induced rapid onset muscular paralysis and myotonia [PMID:15138009].']::text[] WHERE slug = 'spigelia-anthelmia' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
UPDATE public.herbs SET side_effects = ARRAY['A safety assessment of red algae-derived ingredients in cosmetics concluded that 16 such ingredients are safe in present practices of use, though impurities like arsenic and heavy metals should be monitored [PMID:42853009].']::text[] WHERE slug = 'porphyra-yezoensis' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
UPDATE public.herbs SET side_effects = ARRAY['The seeds of Vigna trilobata contain anti-nutritional substances, including tannins and hydrogen cyanide [PMID:12775370].']::text[] WHERE slug = 'vigna-trilobata' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
UPDATE public.herbs SET side_effects = ARRAY['A. mollissima is described as a carcinogenic herb due to its aristolochic acid content [PMID:22953906].', 'In vitro assays using HEK-293 and Vero cells demonstrated that Xungufeng (A. mollissima) is significantly more toxic than Baiying [PMID:22953906].']::text[] WHERE slug = 'aristolochia-mollissima' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
UPDATE public.herbs SET side_effects = ARRAY['In clinical trials of PTAH, 90.4% of participants experienced treatment-related adverse events, most of which were mild (52.6%) or moderate (35.2%), primarily consisting of gastrointestinal, respiratory, and dermatologic manifestations [PMID:34971646].', 'Severe treatment-related adverse events occurred in 2.5% of participants [PMID:34971646].']::text[] WHERE slug = 'arachis-hypogaea' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
UPDATE public.herbs SET side_effects = ARRAY['In a non-clinical safety evaluation in Wistar rats, camelina oil showed no acute toxicity at a single oral dose of 5000 mg/kg and no significant adverse effects during a 12-week sub-chronic toxicity study at doses up to 1000 mg/kg [PMID:39005736].']::text[] WHERE slug = 'camelina-sativa' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
UPDATE public.herbs SET side_effects = ARRAY['A detergent developed from C. sinensis var. assamica seed saponins was found to be non-toxic in mice with an LD50 exceeding 14 g/kg [PMID:28990656].', 'Green tea leaf extract microcapsules showed no cytotoxicity [PMID:29739579].']::text[] WHERE slug = 'camellia-sinensis-var-assamica' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
