UPDATE public.herbs SET side_effects = ARRAY['General safety assessments for red algae-derived ingredients in cosmetics note that impurities such as arsenic, heavy metals, and pesticides may be present, requiring good manufacturing practices [PMID:42853009].']::text[] WHERE slug = 'phymatolithon-calcareum' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
UPDATE public.herbs SET side_effects = ARRAY['Retail samples of P. eryngii have been found to be contaminated with Listeria spp., including L. monocytogenes, in some market surveys [PMID:38440672, PMID:36778843].']::text[] WHERE slug = 'pleurotus-eryngii' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
