UPDATE public.herbs SET side_effects = ARRAY['Wood dust from E. europaeus can cause IgE-mediated type I allergy, manifesting as rhinitis and conjunctivitis [PMID:2058813].', 'In rabbit models, E. europaeus lectin induced damage to the enterocyte brush border, including lengthening, distortion, and vesiculation of microvilli [PMID:3249912].']::text[] WHERE slug = 'euonymus-europaeus' AND (side_effects IS NULL OR cardinality(side_effects) = 0);
